import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64
PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64
// ---------------------------------------------------------------------------
// Pass 1: multi-CTA per-row partial reduction.
// The profiled launch used only 16 CTAs (one per row) on 128 SMs, so each row
// is now split across many CTAs (grid = rows * blocks_per_row) to fill the
// device. Each CTA reduces its slice of the row in f64 and accumulates the
// partial sum and sum of squares into a small global workspace via
// red.global.add.f64.
// ---------------------------------------------------------------------------
.visible .entry layernorm_partial(
    .param .u64 in_ptr,
    .param .u64 ws_ptr,
    .param .s32 row_size,
    .param .s32 bpr
)
{
    .reg .pred %p<8>;
    .reg .b32 %r<16>;
    .reg .b64 %rd<24>;
    .reg .f32 %f<8>;
    .reg .f64 %fd<16>;
    .shared .align 8 .f64 s_sum[256];
    .shared .align 8 .f64 s_ssq[256];
    ld.param.u64 %rd1, [in_ptr];
    ld.param.u64 %rd2, [ws_ptr];
    ld.param.s32 %r1, [row_size];
    ld.param.s32 %r4, [bpr];
    mov.u32 %r2, %tid.x;
    mov.u32 %r3, %ctaid.x;
    // row = ctaid.x / bpr ; bid = ctaid.x % bpr
    div.u32 %r5, %r3, %r4;
    mul.lo.u32 %r6, %r5, %r4;
    sub.u32 %r6, %r3, %r6;
    // row base pointer
    mul.lo.s32 %r13, %r5, %r1;
    cvt.u64.u32 %rd3, %r13;
    shl.b64 %rd3, %rd3, 2;
    add.s64 %rd4, %rd1, %rd3;
    mov.f64 %fd1, 0d0000000000000000;
    mov.f64 %fd2, 0d0000000000000000;
    shr.u32 %r7, %r1, 2;
    and.b32 %r8, %r1, 3;
    setp.eq.s32 %p4, %r8, 0;
    @%p4 bra VEC_SETUP;
    // scalar fallback: contiguous slice of scalars per CTA
    add.s32 %r9, %r1, %r4;
    sub.s32 %r9, %r9, 1;
    div.u32 %r9, %r9, %r4;
    mul.lo.s32 %r10, %r6, %r9;
    add.s32 %r11, %r10, %r9;
    min.s32 %r11, %r11, %r1;
    add.s32 %r12, %r10, %r2;
SLOOP:
    setp.lt.s32 %p1, %r12, %r11;
    @!%p1 bra REDUCE;
    cvt.u64.u32 %rd5, %r12;
    shl.b64 %rd5, %rd5, 2;
    add.s64 %rd6, %rd4, %rd5;
    ld.global.f32 %f1, [%rd6];
    cvt.f64.f32 %fd3, %f1;
    add.f64 %fd1, %fd1, %fd3;
    mul.f64 %fd4, %fd3, %fd3;
    add.f64 %fd2, %fd2, %fd4;
    add.s32 %r12, %r12, 256;
    bra SLOOP;
    // vectorized path: contiguous slice of float4 vectors per CTA
VEC_SETUP:
    add.s32 %r9, %r7, %r4;
    sub.s32 %r9, %r9, 1;
    div.u32 %r9, %r9, %r4;
    mul.lo.s32 %r10, %r6, %r9;
    add.s32 %r11, %r10, %r9;
    min.s32 %r11, %r11, %r7;
    add.s32 %r12, %r10, %r2;
VLOOP:
    setp.lt.s32 %p1, %r12, %r11;
    @!%p1 bra VTAIL;
    cvt.u64.u32 %rd5, %r12;
    shl.b64 %rd5, %rd5, 4;
    add.s64 %rd6, %rd4, %rd5;
    ld.global.v4.f32 {%f1, %f2, %f3, %f4}, [%rd6];
    cvt.f64.f32 %fd3, %f1;
    add.f64 %fd1, %fd1, %fd3;
    mul.f64 %fd4, %fd3, %fd3;
    add.f64 %fd2, %fd2, %fd4;
    cvt.f64.f32 %fd3, %f2;
    add.f64 %fd1, %fd1, %fd3;
    mul.f64 %fd4, %fd3, %fd3;
    add.f64 %fd2, %fd2, %fd4;
    cvt.f64.f32 %fd3, %f3;
    add.f64 %fd1, %fd1, %fd3;
    mul.f64 %fd4, %fd3, %fd3;
    add.f64 %fd2, %fd2, %fd4;
    cvt.f64.f32 %fd3, %f4;
    add.f64 %fd1, %fd1, %fd3;
    mul.f64 %fd4, %fd3, %fd3;
    add.f64 %fd2, %fd2, %fd4;
    add.s32 %r12, %r12, 256;
    bra VLOOP;
VTAIL:
    // last CTA of the row folds in up to 3 tail elements
    add.s32 %r13, %r4, -1;
    setp.eq.u32 %p1, %r6, %r13;
    @!%p1 bra REDUCE;
    setp.eq.u32 %p1, %r2, 0;
    @!%p1 bra REDUCE;
    shl.b32 %r13, %r7, 2;
TLOOP:
    setp.lt.s32 %p1, %r13, %r1;
    @!%p1 bra REDUCE;
    cvt.u64.u32 %rd7, %r13;
    shl.b64 %rd7, %rd7, 2;
    add.s64 %rd8, %rd4, %rd7;
    ld.global.f32 %f1, [%rd8];
    cvt.f64.f32 %fd3, %f1;
    add.f64 %fd1, %fd1, %fd3;
    mul.f64 %fd4, %fd3, %fd3;
    add.f64 %fd2, %fd2, %fd4;
    add.s32 %r13, %r13, 1;
    bra TLOOP;
REDUCE:
    // store per-thread partials to shared memory
    cvt.u64.u32 %rd9, %r2;
    shl.b64 %rd9, %rd9, 3;
    mov.u64 %rd10, s_sum;
    add.s64 %rd10, %rd10, %rd9;
    st.shared.f64 [%rd10], %fd1;
    mov.u64 %rd11, s_ssq;
    add.s64 %rd11, %rd11, %rd9;
    st.shared.f64 [%rd11], %fd2;
    bar.sync 0;
    // tree reduction over 256 partials
    mov.u32 %r14, 128;
RLOOP:
    setp.lt.u32 %p1, %r2, %r14;
    @!%p1 bra RSKIP;
    mul.wide.u32 %rd12, %r14, 8;
    mov.u64 %rd10, s_sum;
    add.s64 %rd10, %rd10, %rd9;
    add.s64 %rd13, %rd10, %rd12;
    ld.shared.f64 %fd5, [%rd10];
    ld.shared.f64 %fd6, [%rd13];
    add.f64 %fd5, %fd5, %fd6;
    st.shared.f64 [%rd10], %fd5;
    mov.u64 %rd11, s_ssq;
    add.s64 %rd11, %rd11, %rd9;
    add.s64 %rd13, %rd11, %rd12;
    ld.shared.f64 %fd7, [%rd11];
    ld.shared.f64 %fd8, [%rd13];
    add.f64 %fd7, %fd7, %fd8;
    st.shared.f64 [%rd11], %fd7;
RSKIP:
    bar.sync 0;
    shr.u32 %r14, %r14, 1;
    setp.gt.u32 %p1, %r14, 0;
    @%p1 bra RLOOP;
    // thread 0 accumulates this CTA's partials into the global workspace
    setp.eq.u32 %p1, %r2, 0;
    @!%p1 bra P1_DONE;
    mov.u64 %rd10, s_sum;
    ld.shared.f64 %fd5, [%rd10];
    mov.u64 %rd11, s_ssq;
    ld.shared.f64 %fd6, [%rd11];
    cvt.u64.u32 %rd14, %r5;
    shl.b64 %rd14, %rd14, 4;
    add.s64 %rd15, %rd2, %rd14;
    red.global.add.f64 [%rd15], %fd5;
    add.s64 %rd16, %rd15, 8;
    red.global.add.f64 [%rd16], %fd6;
P1_DONE:
    ret;
}
// ---------------------------------------------------------------------------
// Pass 2: normalize. Every CTA reloads its row's final sum / sum of squares
// from the workspace, recomputes mean and rstd in f64, then applies the
// normalization + affine transform to its slice with vectorized access.
// L2-reuse optimization: the linear CTA id is reversed so the first CTAs
// of this pass process the rows that layernorm_partial streamed last.
// The input (256 MB) is much larger than L2 (96 MB), so only its tail
// survives between the two launches; reversing the mapping lets those
// rows be re-read from L2 instead of DRAM, cutting re-read traffic.
.visible .entry layernorm_normalize(
    .param .u64 in_ptr,
    .param .u64 out_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 ws_ptr,
    .param .s32 row_size,
    .param .s32 bpr,
    .param .f32 eps
)
{
    .reg .pred %p<8>;
    .reg .b32 %r<16>;
    .reg .b64 %rd<24>;
    .reg .f32 %f<24>;
    .reg .f64 %fd<16>;
    ld.param.u64 %rd1, [in_ptr];
    ld.param.u64 %rd2, [out_ptr];
    ld.param.u64 %rd3, [w_ptr];
    ld.param.u64 %rd4, [b_ptr];
    ld.param.u64 %rd5, [ws_ptr];
    ld.param.s32 %r1, [row_size];
    ld.param.s32 %r4, [bpr];
    ld.param.f32 %f1, [eps];
    mov.u32 %r2, %tid.x;
    mov.u32 %r3, %ctaid.x;
    // reverse linear CTA id: rev = nctaid.x - 1 - ctaid.x
    mov.u32 %r14, %nctaid.x;
    sub.u32 %r14, %r14, 1;
    sub.u32 %r3, %r14, %r3;
    div.u32 %r5, %r3, %r4;
    mul.lo.u32 %r6, %r5, %r4;
    sub.u32 %r6, %r3, %r6;
    mul.lo.s32 %r13, %r5, %r1;
    cvt.u64.u32 %rd6, %r13;
    shl.b64 %rd6, %rd6, 2;
    add.s64 %rd7, %rd1, %rd6;
    add.s64 %rd8, %rd2, %rd6;
    // load final row statistics and derive mean / rstd in f64
    cvt.u64.u32 %rd9, %r5;
    shl.b64 %rd9, %rd9, 4;
    add.s64 %rd10, %rd5, %rd9;
    ld.global.f64 %fd1, [%rd10];
    add.s64 %rd11, %rd10, 8;
    ld.global.f64 %fd2, [%rd11];
    cvt.rn.f64.s32 %fd3, %r1;
    div.rn.f64 %fd4, %fd1, %fd3;
    div.rn.f64 %fd5, %fd2, %fd3;
    mul.f64 %fd6, %fd4, %fd4;
    sub.f64 %fd7, %fd5, %fd6;
    cvt.f64.f32 %fd8, %f1;
    add.f64 %fd7, %fd7, %fd8;
    sqrt.rn.f64 %fd9, %fd7;
    mov.f64 %fd10, 0d3FF0000000000000;
    div.rn.f64 %fd11, %fd10, %fd9;
    cvt.rn.f32.f64 %f2, %fd4;
    cvt.rn.f32.f64 %f3, %fd11;
    shr.u32 %r7, %r1, 2;
    and.b32 %r8, %r1, 3;
    setp.eq.s32 %p4, %r8, 0;
    @%p4 bra VEC2_SETUP;
    // scalar fallback
    add.s32 %r9, %r1, %r4;
    sub.s32 %r9, %r9, 1;
    div.u32 %r9, %r9, %r4;
    mul.lo.s32 %r10, %r6, %r9;
    add.s32 %r11, %r10, %r9;
    min.s32 %r11, %r11, %r1;
    add.s32 %r12, %r10, %r2;
SLOOP2:
    setp.lt.s32 %p1, %r12, %r11;
    @!%p1 bra K2_END;
    cvt.u64.u32 %rd12, %r12;
    shl.b64 %rd12, %rd12, 2;
    add.s64 %rd13, %rd7, %rd12;
    ld.global.f32 %f5, [%rd13];
    add.s64 %rd14, %rd3, %rd12;
    ld.global.f32 %f6, [%rd14];
    add.s64 %rd15, %rd4, %rd12;
    ld.global.f32 %f7, [%rd15];
    sub.f32 %f8, %f5, %f2;
    mul.f32 %f8, %f8, %f3;
    fma.rn.f32 %f9, %f8, %f6, %f7;
    add.s64 %rd16, %rd8, %rd12;
    st.global.f32 [%rd16], %f9;
    add.s32 %r12, %r12, 256;
    bra SLOOP2;
VEC2_SETUP:
    add.s32 %r9, %r7, %r4;
    sub.s32 %r9, %r9, 1;
    div.u32 %r9, %r9, %r4;
    mul.lo.s32 %r10, %r6, %r9;
    add.s32 %r11, %r10, %r9;
    min.s32 %r11, %r11, %r7;
    add.s32 %r12, %r10, %r2;
VLOOP2:
    setp.lt.s32 %p1, %r12, %r11;
    @!%p1 bra VTAIL2;
    cvt.u64.u32 %rd12, %r12;
    shl.b64 %rd12, %rd12, 4;
    add.s64 %rd13, %rd7, %rd12;
    ld.global.v4.f32 {%f5, %f6, %f7, %f8}, [%rd13];
    add.s64 %rd14, %rd3, %rd12;
    ld.global.v4.f32 {%f9, %f10, %f11, %f12}, [%rd14];
    add.s64 %rd15, %rd4, %rd12;
    ld.global.v4.f32 {%f13, %f14, %f15, %f16}, [%rd15];
    sub.f32 %f17, %f5, %f2;
    mul.f32 %f17, %f17, %f3;
    fma.rn.f32 %f17, %f17, %f9, %f13;
    sub.f32 %f18, %f6, %f2;
    mul.f32 %f18, %f18, %f3;
    fma.rn.f32 %f18, %f18, %f10, %f14;
    sub.f32 %f19, %f7, %f2;
    mul.f32 %f19, %f19, %f3;
    fma.rn.f32 %f19, %f19, %f11, %f15;
    sub.f32 %f20, %f8, %f2;
    mul.f32 %f20, %f20, %f3;
    fma.rn.f32 %f20, %f20, %f12, %f16;
    add.s64 %rd16, %rd8, %rd12;
    st.global.v4.f32 [%rd16], {%f17, %f18, %f19, %f20};
    add.s32 %r12, %r12, 256;
    bra VLOOP2;
VTAIL2:
    add.s32 %r13, %r4, -1;
    setp.eq.u32 %p1, %r6, %r13;
    @!%p1 bra K2_END;
    setp.eq.u32 %p1, %r2, 0;
    @!%p1 bra K2_END;
    shl.b32 %r13, %r7, 2;
TLOOP2:
    setp.lt.s32 %p1, %r13, %r1;
    @!%p1 bra K2_END;
    cvt.u64.u32 %rd17, %r13;
    shl.b64 %rd17, %rd17, 2;
    add.s64 %rd18, %rd7, %rd17;
    ld.global.f32 %f5, [%rd18];
    add.s64 %rd19, %rd3, %rd17;
    ld.global.f32 %f6, [%rd19];
    add.s64 %rd20, %rd4, %rd17;
    ld.global.f32 %f7, [%rd20];
    sub.f32 %f8, %f5, %f2;
    mul.f32 %f8, %f8, %f3;
    fma.rn.f32 %f9, %f8, %f6, %f7;
    add.s64 %rd21, %rd8, %rd17;
    st.global.f32 [%rd21], %f9;
    add.s32 %r13, %r13, 1;
    bra TLOOP2;
K2_END:
    ret;
}
"""
_ptx_module = None
def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module
def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    module = _get_ptx_module()
    module.function("layernorm_partial")
    module.function("layernorm_normalize")
class ModelNew(nn.Module):
    def __init__(self, normalized_shape: tuple):
        super().__init__()
        self.ln = nn.LayerNorm(normalized_shape=normalized_shape)
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        row_size = 1
        for d in self.ln.normalized_shape:
            row_size *= d
        rows = x.numel() // row_size
        out = torch.empty(x.shape, dtype=x.dtype, device=x.device)
        # Split every row across enough CTAs to fill the GPU (the profiled
        # launch had only 16 CTAs for 128 SMs). A small f64 workspace
        # collects per-CTA partial sums between the two passes.
        blocks_per_row = max(1, (512 + rows - 1) // rows)
        max_useful = max(1, (row_size + 1023) // 1024)
        if blocks_per_row > max_useful:
            blocks_per_row = max_useful
        workspace = torch.zeros((rows, 2), dtype=torch.float64, device=x.device)
        module = _get_ptx_module()
        stream = torch.cuda.current_stream(x.device)
        module.launch(
            "layernorm_partial",
            grid=(rows * blocks_per_row, 1, 1),
            block=(256, 1, 1),
            arguments=[x, workspace, i32(row_size), i32(blocks_per_row)],
            shared_memory=4096,
            stream=stream,
        )
        module.launch(
            "layernorm_normalize",
            grid=(rows * blocks_per_row, 1, 1),
            block=(256, 1, 1),
            arguments=[x, out, self.ln.weight, self.ln.bias, workspace, i32(row_size), i32(blocks_per_row), f32(self.ln.eps)],
            shared_memory=0,
            stream=stream,
        )
        return out

